import { useId } from "react";

/** The AR monogram (same drawing as public/brand/ar-monogram.svg; generated by scripts/make-logos.py). */
export const MONOGRAM_PATHS = [
  "M60 18 H68 V100 H60 Z",
  "M60 18 H64.4 L27.4 100 H23 Z",
  "M36.2 70.4 H60 V73.4 H34.9 Z",
  "M68 18 H82 C96.5 18 103 26.5 103 38 C103 49.5 96.5 58 82 58 H68 V54.2 H81 C91.6 54.2 95.6 48 95.6 38 C95.6 28 91.6 21.8 81 21.8 H68 Z",
  "M75.5 58 H84 L109 100 H100 Z",
  "M53 16.4 H68 V19 H53 Z",
  "M15 98.6 H33 V101.2 H15 Z",
  "M53 98.6 H75 V101.2 H53 Z",
  "M94 98.6 H113 V101.2 H94 Z",
];

type Props = {
  className?: string;
  /** "gradient" (champagne metal), or any CSS colour. */
  fill?: string;
  /** Outline-drawing mode for the opening sequence. */
  draw?: boolean;
  title?: string;
};

export default function Monogram({ className, fill = "gradient", draw = false, title }: Props) {
  const id = useId().replace(/:/g, "");
  const paint = fill === "gradient" ? `url(#g${id})` : fill;
  return (
    <svg viewBox="13 14 102 90" className={className} role={title ? "img" : undefined} aria-hidden={title ? undefined : true} aria-label={title}>
      {title && <title>{title}</title>}
      <defs>
        <linearGradient id={`g${id}`} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor="#F3E3BC" />
          <stop offset=".38" stopColor="#D6B477" />
          <stop offset=".7" stopColor="#B8955C" />
          <stop offset="1" stopColor="#E2C68E" />
        </linearGradient>
      </defs>
      {MONOGRAM_PATHS.map((d, i) =>
        draw ? (
          <path key={i} d={d} pathLength={1} data-draw fill={paint} fillOpacity={0} stroke={paint} strokeWidth={0.6} strokeDasharray="1 1" strokeDashoffset={1} />
        ) : (
          <path key={i} d={d} fill={paint} />
        ),
      )}
    </svg>
  );
}
